let taskResources=[],resourcesLoading=false,resourceGeneration=0;
const resourceStatus=document.getElementById('resourceStatus'),resourceList=document.getElementById('resourceList'),resourceFiles=document.getElementById('resourceFiles');
function normalizeSourceUrl(input){const raw=input.trim();if(!raw)throw new Error('הוסיפו כתובת של מקור הידע.');const url=new URL(/^[a-z][a-z\d+.-]*:/i.test(raw)?raw:'https://'+raw);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw new Error('יש לצרף קישור HTTP או HTTPS תקין, ללא סיסמה.');return url.href;}
function resetResources(){resourceGeneration++;taskResources=[];resourceList.replaceChildren();resourceStatus.textContent='';resourceFiles.value='';['sourceTitle','sourceUrl','sourceNote'].forEach(id=>document.getElementById(id).value='');}
function showResources(){resourceList.replaceChildren();taskResources.forEach((r,i)=>{const row=el('div',null,'side-row');row.append(el('span',(r.type==='pdf'?'📄 ':'🔗 ')+r.title));const remove=el('button','הסרה','secondary');remove.type='button';remove.disabled=resourcesLoading;remove.onclick=()=>{taskResources.splice(i,1);showResources()};row.append(remove);resourceList.append(row)})}
document.getElementById('addSource').onclick=()=>{if(resourcesLoading)return;if(taskResources.length>=8){resourceStatus.textContent='אפשר לצרף עד שמונה מקורות ונספחים.';return}try{const title=document.getElementById('sourceTitle').value.trim(),url=normalizeSourceUrl(document.getElementById('sourceUrl').value);if(!title)throw new Error('הוסיפו כותרת שתסביר לילד מה יש בקישור.');if(taskResources.some(r=>r.url===url))throw new Error('הקישור הזה כבר צורף.');taskResources.push({type:'link',title,url,kind:document.getElementById('sourceKind').value,note:document.getElementById('sourceNote').value.trim()});['sourceTitle','sourceUrl','sourceNote'].forEach(id=>document.getElementById(id).value='');showResources();resourceStatus.textContent='✓ מקור הידע נוסף למשימה.'}catch(e){resourceStatus.textContent=e.message}};
resourceFiles.onchange=async()=>{if(resourcesLoading)return;resourcesLoading=true;resourceFiles.disabled=true;const generation=resourceGeneration;const files=Array.from(resourceFiles.files);showResources();try{for(const file of files){if(taskResources.length>=8)throw new Error('אפשר לצרף עד שמונה מקורות ונספחים.');if(file.size>2*1024*1024)throw new Error('קובץ PDF יכול להיות עד 2 MB.');const header=await file.slice(0,5).text();if(header!=='%PDF-')throw new Error('אפשר לצרף כאן קובצי PDF בלבד. לצילומים השתמשו באזור צילומי הלוח.');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('קריאת הקובץ נכשלה.'));reader.readAsDataURL(new Blob([file],{type:'application/pdf'}))});if(generation!==resourceGeneration)return;taskResources.push({type:'pdf',title:file.name,filename:file.name,src});resourceStatus.textContent='✓ הנספח צורף למשימה.';}}catch(e){if(generation===resourceGeneration)resourceStatus.textContent=e.message}finally{resourcesLoading=false;resourceFiles.disabled=false;resourceFiles.value='';showResources()}};
function renderTaskResources(container,resources){container.append(el('h4','נספחים ומקורות ידע'));for(const r of resources){const row=el('div');row.style.cssText='padding:10px 0;border-top:1px solid #e5eae4';const a=el('a',(r.type==='pdf'?'📄 ':'🔗 ')+r.title);a.style.cssText='color:#216551;overflow-wrap:anywhere';if(r.type==='pdf'){if(typeof r.src!=='string'||!r.src.startsWith('data:application/pdf;base64,'))continue;a.href=r.src;a.download=r.filename||'worksheet.pdf';row.append(a,el('div','קובץ PDF להורדה','meta'));}else{try{a.href=normalizeSourceUrl(r.url)}catch{continue}a.target='_blank';a.rel='noopener noreferrer';row.append(a,el('div',(r.kind||'מקור ידע')+' · '+new URL(a.href).hostname+' · נפתח באתר חיצוני','meta'));if(r.note)row.append(el('p',r.note));}container.append(row)}}
